// =====================================================================
// ZENTRALE KONFIGURATION – hier pflegen
// DEBUG-STAND: Lieferschein-basiertes Fulfillment (Ansatz A), rein lesend.
// =====================================================================
const CONFIG = {
  // --- Zeitfenster ------------------------------------------------------
  fensterMinuten: 3000,              // Debug-Fenster (~50 h)
  zeitzone: 'Europe/Berlin',

  // --- Abgrenzung der Altbestellungen (verifiziert 2026-08-10) ----------
  kShopAlt: 3,                       // migrierter WooCommerce-Shop (in der SQL fest)
  bestellnummerFeld: 'cBestellNr',   // entspricht Shopify order.name (ohne '#')
  artikelnummerFeld: 'cArtNr',       // wird gegen Shopify sku gemappt
  shopifyNamePrefix: '',

  // --- Shopify ----------------------------------------------------------
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',
  batchGroesse: 25,                  // Bestellungen pro GraphQL-Sammelabfrage
  foProBestellung: 10,               // FulfillmentOrders je Bestellung
  lineItemsProFo: 50,                // Positionen je FulfillmentOrder
  fulfillmentsProBestellung: 25,     // vorhandene Fulfillments (Trackingnr-Abgleich)

  // --- Betrieb ----------------------------------------------------------
  testLimit: 0,        // 0 = alle Bestellungen; >0 = nur die ersten N (Testbetrieb)
  dryRun: true,        // true = KEIN Schreib-Call an Shopify
  notifyCustomer: false,
  trackingSenden: true,   // Trackingnr des Lieferscheins mitschicken
  reportMailSenden: true,
  reportEmpfaenger: 'jesse.balsam@buecherbuechse.de'
};

return [{ json: { config: CONFIG } }];

// SQL liefert EINE ZEILE PRO LIEFERSCHEINPOSITION.
// Hier: Buendelung zu einem Item pro LIEFERSCHEIN (= eine physische Sendung).
const config = $('Config').first().json.config;
const rows = $input.all().map(i => i.json)
  .filter(r => r && r.kLieferschein !== undefined && r.kLieferschein !== null);

const txt = v => String(v ?? '').trim();
const map = new Map();

for (const r of rows) {
  const key = Number(r.kLieferschein);
  if (!map.has(key)) {
    const nr = txt(r[config.bestellnummerFeld]);
    map.set(key, {
      // --- Lieferschein ---
      kLieferschein:    key,
      cLieferscheinNr:  txt(r.cLieferscheinNr) || null,
      dVersendet:       r.dVersendet ?? null,
      trackingNummer:   txt(r.cIdentCode) || null,
      trackingCarrier:  txt(r.Carrier) || null,
      // --- Bestellung ---
      kBestellung:      Number(r.kBestellung),
      bestellnummer:    nr,
      shopifyOrderName: config.shopifyNamePrefix + nr,
      // --- Positionen ---
      positionen:       [],
      runId:            $execution.id
    });
  }

  const ls   = map.get(key);
  const art  = txt(r[config.artikelnummerFeld]);
  const menge = Number(r.fMengeGeliefert) || 0;

  // Gleiche Artikelnummer innerhalb EINES Lieferscheins zusammenfassen
  const vorhanden = ls.positionen.find(p => p.cArtNr === art);
  if (vorhanden) {
    vorhanden.mengeGeliefert += menge;
    vorhanden.mengeBestellt  += Number(r.nMengeBestellt) || 0;
    vorhanden.kBestellPos.push(Number(r.kBestellPos));
  } else {
    ls.positionen.push({
      cArtNr:         art,
      cArtikelname:   txt(r.cArtikelname) || null,
      mengeGeliefert: menge,
      mengeBestellt:  Number(r.nMengeBestellt) || 0,
      kBestellPos:    [Number(r.kBestellPos)]
    });
  }
}

let alle = [...map.values()];

// Chronologisch: entscheidend fuer die Restmengen-Reihenfolge im Matching
alle.sort((a, b) =>
  String(a.dVersendet).localeCompare(String(b.dVersendet)) ||
  a.kLieferschein - b.kLieferschein);

// testLimit begrenzt BESTELLUNGEN, nie Lieferscheine – sonst wird eine
// Bestellung zerrissen und die Restmengen-Logik stimmt nicht mehr.
if (config.testLimit > 0) {
  const erlaubt = new Set();
  for (const ls of alle) {
    if (erlaubt.size >= config.testLimit && !erlaubt.has(ls.shopifyOrderName)) continue;
    erlaubt.add(ls.shopifyOrderName);
  }
  alle = alle.filter(ls => erlaubt.has(ls.shopifyOrderName));
}

return alle.map(json => ({ json }));

// Lieferscheine nach Bestellung gruppieren, dann Bestellungen in Batches
// schneiden – ein GraphQL-Lookup je Batch.
const config = $('Config').first().json.config;
const alle   = $input.all().map(i => i.json);

const perOrder = new Map();
for (const ls of alle) {
  const k = ls.shopifyOrderName;
  if (!perOrder.has(k)) {
    perOrder.set(k, {
      shopifyOrderName: k,
      bestellnummer:    ls.bestellnummer,
      kBestellung:      ls.kBestellung,
      lieferscheine:    []
    });
  }
  perOrder.get(k).lieferscheine.push(ls);
}

// Innerhalb der Bestellung: Lieferscheine in Versandreihenfolge.
for (const o of perOrder.values()) {
  o.lieferscheine.sort((a, b) =>
    String(a.dVersendet).localeCompare(String(b.dVersendet)) ||
    a.kLieferschein - b.kLieferschein);
  o.anzahlLieferscheine = o.lieferscheine.length;
}

const bestellungen = [...perOrder.values()];
const groesse = Math.max(1, Math.min(Number(config.batchGroesse) || 25, 100));

const out = [];
for (let i = 0; i < bestellungen.length; i += groesse) {
  const teil = bestellungen.slice(i, i + groesse);
  out.push({ json: {
    batchIndex:          out.length,
    anzahlBestellungen:  teil.length,
    anzahlLieferscheine: teil.reduce((s, o) => s + o.lieferscheine.length, 0),
    bestellungen:        teil
  }});
}
return out;

// Sammel-Lookup je Batch. Wir brauchen jetzt drei Dinge pro Bestellung:
//   1. offene FulfillmentOrder-Positionen mit sku + remainingQuantity
//   2. bereits hinterlegte Trackingnummern (Doppelt-Erkennung)
//   3. den aktuellen Fulfillment-Status
const config = $('Config').first().json.config;
const batch  = $input.first().json;

const q = batch.bestellungen.map(o => 'name:' + o.shopifyOrderName).join(' OR ');

const query = `query($q: String!) {
  orders(first: ${Math.max(1, batch.anzahlBestellungen)}, query: $q) {
    edges { node {
      id
      name
      closed
      cancelledAt
      displayFulfillmentStatus
      fulfillments(first: ${config.fulfillmentsProBestellung}) {
        id
        status
        createdAt
        trackingInfo(first: 5) { number company }
      }
      fulfillmentOrders(first: ${config.foProBestellung}) {
        edges { node {
          id
          status
          lineItems(first: ${config.lineItemsProFo}) {
            edges { node {
              id
              sku
              productTitle
              variantTitle
              totalQuantity
              remainingQuantity
              lineItem { id sku name }
            } }
          }
        } }
      }
    } }
  }
}`;

return [{ json: {
  batchIndex:          batch.batchIndex,
  anzahlBestellungen:  batch.anzahlBestellungen,
  anzahlLieferscheine: batch.anzahlLieferscheine,
  bestellungen:        batch.bestellungen,
  gqlBody: JSON.stringify({ query, variables: { q } })
}}];

// KERN: Zuordnung JTL-Lieferscheinposition -> Shopify FulfillmentOrder-Position.
// Ausgabe: ein Item pro LIEFERSCHEIN mit fertigem Plan (noch ohne Schreib-Call).
const config = $('Config').first().json.config;
const src    = $('Query bauen (Orders-Lookup)').first().json;
const resp   = $input.first().json;

const FO_OFFEN  = ['OPEN', 'IN_PROGRESS', 'SCHEDULED'];
const normName  = s => String(s ?? '').replace(/^#/, '').trim();
const normSku   = s => String(s ?? '').trim().toUpperCase();
const alsListe  = v => Array.isArray(v) ? v : (v?.edges || []).map(e => e.node);

// --- Harter Fehler: ganzer Batch bekommt error -------------------------
if (resp?.error || resp?.errors) {
  const msg = 'Orders-Lookup fehlgeschlagen: ' +
              JSON.stringify(resp.error || resp.errors).slice(0, 500);
  const out = [];
  for (const best of src.bestellungen) {
    for (const ls of best.lieferscheine) {
      out.push({ json: { ...ls, batchIndex: src.batchIndex,
        shopifyStatus: 'error', shopifyAktion: 'skip', shopifyMessage: msg,
        zuordnung: [], lineItemsByFulfillmentOrder: [],
        summeGeliefert: ls.positionen.reduce((s, p) => s + p.mengeGeliefert, 0),
        summeZugeordnet: 0 } });
    }
  }
  return out;
}

const gefunden = new Map();
for (const e of (resp?.data?.orders?.edges || [])) {
  gefunden.set(normName(e.node.name), e.node);
}

const out = [];

for (const best of src.bestellungen) {
  const order = gefunden.get(normName(best.shopifyOrderName));

  // ---- Bestellung nicht in Shopify -----------------------------------
  if (!order) {
    for (const ls of best.lieferscheine) {
      out.push({ json: { ...ls, batchIndex: src.batchIndex,
        shopifyStatus: 'skipped_not_found', shopifyAktion: 'skip',
        shopifyMessage: 'Keine Shopify-Bestellung mit name=' + ls.shopifyOrderName,
        zuordnung: [], lineItemsByFulfillmentOrder: [],
        summeGeliefert: ls.positionen.reduce((s, p) => s + p.mengeGeliefert, 0),
        summeZugeordnet: 0 } });
    }
    continue;
  }

  // ---- vorhandene Trackingnummern (Doppelt-Erkennung) ----------------
  const trackingVorhanden = new Set();
  for (const f of alsListe(order.fulfillments)) {
    for (const t of alsListe(f?.trackingInfo)) {
      if (t?.number) trackingVorhanden.add(normSku(t.number));
    }
  }

  // ---- Restmengen-Pool aus den OFFENEN FulfillmentOrders -------------
  // Der Pool wird ueber alle Lieferscheine dieser Bestellung hinweg
  // lokal verbraucht -> mehrere Lieferscheine im selben Run kollidieren nicht.
  const pool      = [];
  const skusInFo  = new Set();   // Diagnose: SKU in Shopify ueberhaupt vorhanden?
  const foPosAlle = [];          // Diagnose: ALLE FO-Positionen, roh
  const foStatusListe = [];

  for (const fe of (order.fulfillmentOrders?.edges || [])) {
    const fo = fe.node;
    foStatusListe.push(fo.status);
    for (const le of (fo.lineItems?.edges || [])) {
      const li  = le.node;
      const sku = normSku(li.sku ?? li.lineItem?.sku);
      if (sku) skusInFo.add(sku);
      foPosAlle.push({
        foStatus: fo.status,
        sku:      sku || null,
        skuRoh:   li.sku ?? null,
        skuLineItem: li.lineItem?.sku ?? null,
        titel:    li.productTitle || li.lineItem?.name || null,
        variante: li.variantTitle || null,
        gesamt:   Number(li.totalQuantity) || 0,
        rest:     Number(li.remainingQuantity) || 0
      });
      if (!FO_OFFEN.includes(fo.status)) continue;
      const rest = Number(li.remainingQuantity) || 0;
      if (rest <= 0) continue;
      pool.push({
        foId:   fo.id,
        foliId: li.id,
        sku,
        titel:  li.productTitle || li.lineItem?.name || null,
        rest
      });
    }
  }

  // ---- Lieferscheine in Versandreihenfolge abarbeiten ----------------
  for (const ls of best.lieferscheine) {
    const basis = { ...ls,
      batchIndex:                 src.batchIndex,
      shopifyOrderId:             order.id,
      shopifyOrderNameGefunden:   order.name,
      shopifyOrderClosed:         !!order.closed,
      shopifyStatusVorher:        order.displayFulfillmentStatus,
      anzahlFulfillmentOrders:    foStatusListe.length,
      fulfillmentOrderStatus:     foStatusListe,
      offeneShopifyPositionen:    pool.filter(p => p.rest > 0).length,
      shopifySkus:                [...skusInFo],
      shopifyFoPositionen:        foPosAlle,
      anzahlFoPositionen:         foPosAlle.length,
      anzahlFoPositionenOhneSku:  foPosAlle.filter(p => !p.sku).length
    };
    const skip = (status, message) => out.push({ json: { ...basis,
      shopifyAktion: 'skip', shopifyStatus: status, shopifyMessage: message,
      zuordnung: [], summeGeliefert: ls.positionen.reduce((s,p)=>s+p.mengeGeliefert,0),
      summeZugeordnet: 0, lineItemsByFulfillmentOrder: [] } });

    if (order.cancelledAt) { skip('skipped_cancelled', 'Bestellung in Shopify storniert'); continue; }

    if (ls.trackingNummer && trackingVorhanden.has(normSku(ls.trackingNummer))) {
      skip('skipped_already_shipped',
           'Trackingnummer ' + ls.trackingNummer + ' ist in Shopify bereits hinterlegt');
      continue;
    }

    // ---- Positionsweise zuordnen ------------------------------------
    const zuordnung = [];
    const perFo     = new Map();

    for (const p of ls.positionen) {
      const sku = normSku(p.cArtNr);
      let offen = Math.round(Number(p.mengeGeliefert) || 0);
      const treffer = [];

      for (const k of pool) {
        if (offen <= 0) break;
        if (k.rest <= 0 || k.sku !== sku) continue;
        const n = Math.min(offen, k.rest);
        k.rest -= n;
        offen  -= n;
        treffer.push({ fulfillmentOrderId: k.foId, fulfillmentOrderLineItemId: k.foliId, menge: n });
        if (!perFo.has(k.foId)) perFo.set(k.foId, []);
        perFo.get(k.foId).push({ id: k.foliId, quantity: n });
      }

      const zugeordnet = Math.round(Number(p.mengeGeliefert) || 0) - offen;
      let pStatus;
      if (zugeordnet > 0 && offen === 0)      pStatus = 'ok';
      else if (zugeordnet > 0)                pStatus = 'teilweise';
      else if (!sku)                          pStatus = 'jtl_ohne_artikelnummer';
      else if (skusInFo.has(sku))             pStatus = 'kein_rest_offen';
      else                                    pStatus = 'sku_nicht_in_shopify';

      zuordnung.push({
        cArtNr:              p.cArtNr,
        cArtikelname:        p.cArtikelname,
        mengeGeliefert:      p.mengeGeliefert,
        mengeZugeordnet:     zugeordnet,
        mengeOffenGeblieben: offen,
        status:              pStatus,
        treffer
      });
    }

    const summeGeliefert  = zuordnung.reduce((s, z) => s + (Number(z.mengeGeliefert) || 0), 0);
    const summeZugeordnet = zuordnung.reduce((s, z) => s + z.mengeZugeordnet, 0);
    const lineItemsByFulfillmentOrder = [...perFo.entries()]
      .map(([foId, items]) => ({ fulfillmentOrderId: foId, fulfillmentOrderLineItems: items }));

    // ---- Entscheidung ----------------------------------------------
    let status, aktion, msg = null;
    if (summeZugeordnet > 0) {
      const teil = zuordnung.some(z => z.mengeOffenGeblieben > 0);
      status = config.dryRun ? 'ready_dry_run' : 'ready';
      aktion = config.dryRun ? 'dry_run' : 'create';
      if (teil) msg = 'TEILZUORDNUNG – nicht alle Lieferscheinpositionen konnten zugeordnet werden';
    } else if (order.displayFulfillmentStatus === 'FULFILLED') {
      status = 'skipped_already_fulfilled';
      aktion = 'skip';
      msg    = 'Bestellung in Shopify bereits vollstaendig versendet';
    } else if (!pool.length) {
      status = 'skipped_no_open_lineitems';
      aktion = 'skip';
      msg    = 'Keine offene FulfillmentOrder-Position (Status: ' + order.displayFulfillmentStatus + ')';
    } else {
      status = 'skipped_no_match';
      aktion = 'skip';
      msg    = 'Keine Position zuordenbar – Artikelnummern passen nicht zu den Shopify-SKUs';
    }

    out.push({ json: { ...basis,
      shopifyAktion: aktion, shopifyStatus: status, shopifyMessage: msg,
      zuordnung, summeGeliefert, summeZugeordnet, lineItemsByFulfillmentOrder } });
  }
}

return out;

// Body fuer fulfillmentCreate – positionsgenau, ein Call pro Lieferschein.
const config = $('Config').first().json.config;
const item   = $input.first().json;

const fulfillment = {
  notifyCustomer: config.notifyCustomer,
  lineItemsByFulfillmentOrder: item.lineItemsByFulfillmentOrder
};

if (config.trackingSenden && item.trackingNummer) {
  fulfillment.trackingInfo = {
    number:  item.trackingNummer,
    company: item.trackingCarrier || 'DHL'
  };
}

const body = {
  query: `mutation fulfillmentCreate($fulfillment: FulfillmentInput!) {
    fulfillmentCreate(fulfillment: $fulfillment) {
      fulfillment {
        id
        status
        createdAt
        totalQuantity
        trackingInfo(first: 5) { number company url }
      }
      userErrors { field message }
    }
  }`,
  variables: { fulfillment }
};

return [{ json: { ...item, gqlBody: JSON.stringify(body) } }];

const src  = $('⚠️ Query bauen (fulfillmentCreate)').item.json;
const resp = $input.first().json;

if (resp?.error || resp?.errors) {
  return [{ json: { ...src, shopifyStatus: 'error',
    shopifyMessage: 'HTTP/GraphQL-Fehler: ' + JSON.stringify(resp.error || resp.errors).slice(0, 500) } }];
}

const res  = resp?.data?.fulfillmentCreate;
const errs = res?.userErrors || [];
if (errs.length) {
  return [{ json: { ...src, shopifyStatus: 'error',
    shopifyMessage: 'userErrors: ' + JSON.stringify(errs) } }];
}

return [{ json: { ...src, shopifyStatus: 'done', shopifyMessage: null,
                  shopifyFulfillmentId: res?.fulfillment?.id || null } }];

// Zusammenfassung ueber alle Batches. Kein Schreibzugriff.
const config = $('Config').first().json.config;
const zeilen = $input.all().map(i => i.json);

const zaehler = {};
for (const z of zeilen) zaehler[z.entscheidung] = (zaehler[z.entscheidung] || 0) + 1;

const bestellungen = new Set(zeilen.map(z => z.bestellnummer));
const wuerdeMelden = zeilen.filter(z => z.wuerdeMelden === 'JA');
const teilzuordnung = wuerdeMelden.filter(z => (z.hinweis || '').startsWith('TEILZUORDNUNG'));
const problemStatus = ['skipped_no_match', 'skipped_not_found', 'skipped_no_open_lineitems', 'error'];
const probleme = zeilen.filter(z => problemStatus.includes(z.entscheidung));

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const trStat = Object.entries(zaehler).sort((a,b)=>b[1]-a[1])
  .map(([k,v]) => '<tr><td>' + esc(k) + '</td><td align="right">' + v + '</td></tr>').join('');

const spalten = ['bestellnummer','cLieferscheinNr','versendetAm',
                 'shopifyStatusVorher','positionenJTL','shopifySkus','shopifyPositionen',
                 'zuordnung','wuerdeMelden','entscheidung'];
const kopf = '<tr>' + spalten.map(s => '<th align="left">' + s + '</th>').join('') + '</tr>';
const body = zeilen.slice(0, 200).map(z =>
  '<tr>' + spalten.map(s => '<td>' + esc(z[s]) + '</td>').join('') + '</tr>').join('');

const zusammenfassung = {
  runId:                 $execution.id,
  dryRun:                config.dryRun,
  fensterMinuten:        config.fensterMinuten,
  testLimit:             config.testLimit,
  lieferscheineGesamt:   zeilen.length,
  bestellungenGesamt:    bestellungen.size,
  wuerdeGemeldet:        wuerdeMelden.length,
  davonTeilzuordnung:    teilzuordnung.length,
  proEntscheidung:       zaehler,
  problemfaelle:         probleme.length,
  problemBeispiele:      probleme.slice(0, 25).map(z => ({
                            bestellnummer: z.bestellnummer,
                            lieferschein: z.cLieferscheinNr,
                            entscheidung: z.entscheidung,
                            positionen: z.positionenJTL,
                            hinweis: z.hinweis })),
  teilzuordnungBeispiele: teilzuordnung.slice(0, 25).map(z => ({
                            bestellnummer: z.bestellnummer,
                            lieferschein: z.cLieferscheinNr,
                            zuordnung: z.zuordnung }))
};

return [{ json: {
  ...zusammenfassung,
  tabelle: zeilen,
  titel:  'JTL -> Shopify Fulfillment DEBUG – Run ' + $execution.id,
  sendto: config.reportEmpfaenger,
  mailText:
    '<h3>JTL &rarr; Shopify Fulfillment (Debug)</h3>' +
    '<p>Dry-Run: <b>' + config.dryRun + '</b> &middot; Fenster: <b>' +
      config.fensterMinuten + ' min</b><br>' +
    'Lieferscheine: <b>' + zeilen.length + '</b> aus <b>' + bestellungen.size +
      '</b> Bestellungen &middot; wuerde melden: <b>' + wuerdeMelden.length + '</b>' +
      ' (davon Teilzuordnung: ' + teilzuordnung.length + ')</p>' +
    '<table border="1" cellpadding="4" cellspacing="0">' + trStat + '</table>' +
    '<h4>Detail (max. 200)</h4>' +
    '<table border="1" cellpadding="4" cellspacing="0" style="font-size:11px">' +
      kopf + body + '</table>'
}}];

// FLACHE DEBUG-TABELLE: eine Zeile pro Lieferschein.
// In n8n als Table-View lesbar – zeigt Zuordnung und geplante Aktion.
const config = $('Config').first().json.config;
const items  = $input.all().map(i => i.json)
  .filter(i => i && i.kLieferschein !== undefined);

const perOrder = {};
for (const i of items) perOrder[i.bestellnummer] = (perOrder[i.bestellnummer] || 0) + 1;

const posText = z =>
  z.cArtNr + ' ' + z.mengeZugeordnet + '/' + z.mengeGeliefert +
  (z.status === 'ok' ? '' : ' [' + z.status + ']');

items.sort((a, b) =>
  String(a.bestellnummer).localeCompare(String(b.bestellnummer)) ||
  String(a.dVersendet).localeCompare(String(b.dVersendet)));

return items.map(i => {
  const z = i.zuordnung || [];
  return { json: {
    // --- Bestellung ---
    bestellnummer:            i.bestellnummer,
    lieferscheineDerBestellung: perOrder[i.bestellnummer] || 1,
    kBestellung:              i.kBestellung,
    // --- Lieferschein ---
    cLieferscheinNr:          i.cLieferscheinNr,
    versendetAm:              i.dVersendet,
    trackingNummer:           i.trackingNummer,
    carrier:                  i.trackingCarrier,
    // --- Shopify vorher ---
    shopifyGefunden:          i.shopifyOrderId ? 'ja' : 'nein',
    shopifyStatusVorher:      i.shopifyStatusVorher ?? null,
    shopifyOrderClosed:       i.shopifyOrderClosed ?? null,
    offeneShopifyPositionen:  i.offeneShopifyPositionen ?? null,
    // --- Zuordnung ---
    positionenJTL:            (i.positionen || []).map(x => x.cArtNr + ' x' + x.mengeGeliefert).join(' | '),
    shopifySkus:              (i.shopifySkus && i.shopifySkus.length)
                                ? i.shopifySkus.join(' | ')
                                : (i.anzahlFoPositionen ? '(alle Positionen OHNE sku)' : '(keine FO-Position)'),
    shopifyPositionen:        (i.shopifyFoPositionen || []).map(p =>
                                (p.sku || '(ohne sku)') + ' rest=' + p.rest +
                                (p.titel ? ' «' + p.titel + '»' : '')).join(' | '),
    foPositionenOhneSku:      i.anzahlFoPositionenOhneSku ?? null,
    zuordnung:                z.length ? z.map(posText).join(' | ') : '(nicht geprueft)',
    mengeGeliefert:           i.summeGeliefert ?? null,
    mengeZugeordnet:          i.summeZugeordnet ?? null,
    // --- Entscheidung ---
